<script setup lang="ts">
import { computed, ref, onBeforeUnmount } from 'vue'
import AppSidebar from '../../components/AppSidebar.vue'
import BrandLogo from '../../components/BrandLogo.vue'
import UiIcon from '../../components/UiIcon.vue'
import ChatAttachmentCard from '../../components/ChatAttachmentCard.vue'
import { useRoute } from 'vue-router'
const showAttachments=computed(()=>usePreviewRoute.query.attachments==='1')
const usePreviewRoute=useRoute()
const sampleAttachment={name:'项目需求说明.md',url:'/ui/attachment-example.md',size:202,mime:'text/markdown'}
const previewAttachment=ref<typeof sampleAttachment|undefined>(sampleAttachment)
const failed=ref(false), expanded=ref(false), draft=ref(''), search=ref(''), agent=ref('博查搜索助手'), notice=ref(''), liked=ref(false)
const records=[{title:'整理近期 AI 行业动态',time:'今天 10:24'},{title:'制定 AI 产品发布会方案',time:'昨天 16:30'},{title:'分析 Q3 用户增长数据',time:'10 月 12 日'},{title:'生成产品需求文档',time:'10 月 11 日'}]
const filtered=computed(()=>records.filter(item=>item.title.includes(search.value)))
const sections=[{title:'大模型与技术进展',heading:'从模型能力，转向实际任务的完成能力',text:'梳理模型更新时，除了推理和多模态能力，还应关注工具调用、任务完成率与使用成本。这些指标更有助于判断是否适合接入产品。',sources:['官方发布','技术文档']},{title:'AI 产品与应用',heading:'办公场景更关注工作流与协作体验',text:'写作、资料整理和数据分析是常见的落地场景。产品体验的关键，是把输入、处理过程和输出连接起来，让用户更容易查看结果与继续操作。',sources:['产品动态','应用案例']},{title:'行业生态与趋势',heading:'把信息转化为可以执行的下一步',text:'阅读行业动态后，可以按产品方向归类，记录潜在机会与待验证假设，再把值得关注的内容整理成一份简短的行动清单。',sources:['行业观察','研究报告']}]
async function copy(){try{await navigator.clipboard.writeText(failed.value?'本次搜索没有取得有效结果。稍后重新搜索，或提供文章链接以便提炼重点。':sections.map(s=>s.title+'\n'+s.heading+'\n'+s.text).join('\n\n'));notice.value='回答已复制'}catch{notice.value='请选中回答内容复制'}}
function send(){if(draft.value.trim()){notice.value='这是样式预览，暂不发送消息';}}

// 演示只使用本地计时器，不发送搜索请求或调用模型。
type DemoToolState = 'waiting' | 'working' | 'done' | 'stopped' | 'skipped'
interface DemoTool { name:string; icon:string; state:DemoToolState; description:string; result:string; elapsed:number; started:number; open:boolean }
const demoShown=ref(false), demoPhase=ref('idle'), typedCount=ref(0), demoSeconds=ref(0)
const demoTools=ref<DemoTool[]>([])
const playing=computed(()=>['preparing','tools','summarizing','writing'].includes(demoPhase.value))
const demoStatus=computed(()=>({preparing:'正在准备检索任务',tools:'正在执行工具',summarizing:'正在整理工具结果',writing:'正在生成回答',done:'回答已生成',stopped:'已停止演示'} as Record<string,string>)[demoPhase.value]||'')
const streamSections=computed(()=>{let remaining=typedCount.value;return sections.map(section=>{const count=Math.max(0,Math.min(section.text.length,remaining));remaining-=section.text.length;return {...section,text:section.text.slice(0,count),visible:count>0,complete:count===section.text.length}}).filter(section=>section.visible)})
const toolStateText=(state:DemoToolState)=>({waiting:'等待执行',working:'执行中',done:'已完成',stopped:'已停止',skipped:'未执行'})[state]
let pendingTimers:Array<ReturnType<typeof setTimeout>>=[], demoTicker:ReturnType<typeof setInterval>|undefined, typingTicker:ReturnType<typeof setInterval>|undefined
function clearDemoTimers(){pendingTimers.forEach(clearTimeout);pendingTimers=[];if(demoTicker)clearInterval(demoTicker);if(typingTicker)clearInterval(typingTicker);demoTicker=undefined;typingTicker=undefined}
function afterDemo(delay:number,action:()=>void){pendingTimers.push(setTimeout(action,delay))}
function stopDemo(){clearDemoTimers();demoPhase.value='stopped';demoTools.value.forEach(tool=>{if(tool.state==='working')tool.state='stopped';else if(tool.state==='waiting')tool.state='skipped'})}
function setScenario(value:boolean){clearDemoTimers();demoShown.value=false;demoPhase.value='idle';failed.value=value;expanded.value=false}
function startDemo(){
clearDemoTimers();failed.value=false;notice.value='';liked.value=false;demoShown.value=true;demoPhase.value='preparing';typedCount.value=0;demoSeconds.value=0;
demoTools.value=[{name:'博查搜索',icon:'search',state:'waiting',description:'检索 AI 行业动态、产品更新与应用趋势',result:'已找到 8 条相关资料，等待下一步读取',elapsed:0,started:0,open:false},{name:'网页读取',icon:'browser',state:'waiting',description:'读取搜索结果，提取正文并核对来源',result:'已读取 5 篇文章，提取 3 个主题与对应来源',elapsed:0,started:0,open:false}];
const started=Date.now();demoTicker=setInterval(()=>{demoSeconds.value=Math.floor((Date.now()-started)/1000);demoTools.value.forEach(tool=>{if(tool.state==='working')tool.elapsed=Math.floor((Date.now()-tool.started)/1000)})},250);
afterDemo(900,()=>{demoPhase.value='tools';demoTools.value[0].state='working';demoTools.value[0].started=Date.now()});
afterDemo(4200,()=>{demoTools.value[0].state='done';demoTools.value[1].state='working';demoTools.value[1].started=Date.now()});
afterDemo(8400,()=>{demoTools.value[1].state='done';demoPhase.value='summarizing'});
afterDemo(9400,()=>{demoPhase.value='writing';const total=sections.reduce((sum,section)=>sum+section.text.length,0);typingTicker=setInterval(()=>{typedCount.value=Math.min(total,typedCount.value+2);if(typedCount.value===total){demoPhase.value='done';clearDemoTimers()}},30)});
}
onBeforeUnmount(clearDemoTimers)

</script>
<template><div class="p-shell b5-page chat-design-preview"><AppSidebar/><div class="preview-columns"><aside class="preview-history"><button class="preview-new" @click="notice='这是独立样式预览，正式会话保持原样'"><UiIcon name="plus"/>新建会话</button><label class="preview-search"><UiIcon name="search"/><input v-model="search" placeholder="搜索会话…" aria-label="搜索示例会话"></label><div class="history-group">今天</div><button v-for="(item,index) in filtered" :key="item.title" class="preview-record" :class="{active:index===0}" @click="notice='当前展示的是聊天页样式示例'"><span class="record-icon"><UiIcon name="chat"/></span><span><strong>{{item.title}}</strong><small>{{item.time}}</small></span><UiIcon name="more"/></button><div class="history-foot"><UiIcon name="chat"/><span>让每一次对话，都有清晰的结果</span></div></aside><main class="preview-chat"><div class="preview-toolbar"><span class="preview-label">聊天页样式预览</span><div class="preview-demo-controls"><button v-if="playing" class="demo-stop" @click="stopDemo"><UiIcon name="stop"/>停止</button><button v-else class="demo-start" @click="startDemo"><UiIcon :name="demoShown?'refresh':'play'"/>{{demoShown?'重新演示':'开始演示'}}</button><div class="scenario-switch" aria-label="选择工具调用展示场景"><button :class="{active:!failed}"  :disabled="playing" @click="setScenario(false)">正常结果</button><button :class="{active:failed}"  :disabled="playing" @click="setScenario(true)">工具异常</button></div></div></div><div class="preview-scroll"><div class="message-column"><article class="preview-user"><div class="preview-user-content"><div class="preview-user-bubble">{{showAttachments?'帮我整理一下附件里的项目需求。':'帮我整理一下近期 AI 行业动态，附上关键来源。'}}</div><ChatAttachmentCard v-if="showAttachments" :file="sampleAttachment"/></div><span class="preview-user-avatar">田</span></article><article class="preview-assistant"><span class="preview-bot"><BrandLogo compact/></span><div class="preview-answer"><div v-if="demoShown" class="demo-execution"><header class="demo-execution-heading"><span class="demo-live-dot" :class="{playing}"/><strong>{{demoStatus}}</strong><span class="demo-total-time">{{demoSeconds}} 秒</span></header><div class="demo-tool-list"><article v-for="(tool,index) in demoTools" :key="tool.name" class="demo-tool" :class="tool.state"><button class="demo-tool-summary" :aria-expanded="tool.open" @click="tool.open=!tool.open"><span class="demo-tool-icon"><UiIcon :name="tool.icon"/></span><span class="demo-tool-copy"><strong>{{tool.name}}</strong><small>{{tool.state==='waiting'?(index===0?'准备检索相关资料':'等待搜索结果，再读取网页'):tool.state==='done'?tool.result:tool.state==='working'?tool.description:toolStateText(tool.state)}}</small></span><span class="demo-tool-state"><span v-if="tool.state==='working'" class="demo-spinner"/><UiIcon v-else-if="tool.state==='done'" name="check"/>{{toolStateText(tool.state)}}<small v-if="tool.state==='working'||tool.state==='done'">{{tool.elapsed}}s</small></span><UiIcon class="demo-expand" name="chevron-down" :class="{open:tool.open}"/></button><div v-if="tool.open" class="demo-tool-detail"><div><span>执行任务</span><p>{{tool.description}}</p></div><div><span>当前结果</span><p>{{tool.state==='done'?tool.result:tool.state==='working'?'等待工具返回结果…':tool.state==='waiting'?'尚未开始执行': '演示已停止，没有继续执行'}}</p></div></div></article></div><p class="demo-execution-note">本地过程演示 · 不调用真实工具</p></div><div v-else class="tool-process" :class="{failed}"><button class="process-summary" :aria-expanded="expanded" @click="expanded=!expanded"><span class="process-icon"><UiIcon :name="failed?'info':'check'"/></span><span class="process-copy"><strong>{{failed?'联网搜索暂时不可用':'已完成联网搜索'}}</strong><small>{{failed?'博查搜索 · 服务配置异常':'博查搜索 · 检索与整理 8 条资料'}}</small></span><span class="process-detail">{{expanded?'收起':'查看过程'}}<UiIcon name="chevron-down" :class="{expanded}"/></span></button><div v-if="expanded" class="process-body"><div><span>工具</span><strong>博查搜索</strong></div><div><span>查询内容</span><strong>AI 行业动态、产品更新与应用趋势</strong></div><div><span>执行结果</span><strong>{{failed?'搜索服务配置异常，本次未取得实时资料':'示例检索完成，已提取主要信息与来源'}}</strong></div></div></div><template v-if="!failed&&(!demoShown||['writing','done','stopped'].includes(demoPhase)&&typedCount>0)"><p class="answer-intro">可以，我按<strong>技术进展、产品应用、行业趋势</strong>三个方向整理，方便你快速抓住重点。</p><p class="example-note">以下为排版示例，内容与来源标签用于展示，不代表实时新闻。</p><section v-for="(section,index) in (demoShown?streamSections:sections)" :key="section.title" class="answer-section"><h2><span>{{index+1}}</span>{{section.title}}<i/></h2><h3>{{section.heading}}</h3><p>{{section.text}}<span v-if="demoShown&&demoPhase==='writing'&&index===streamSections.length-1" class="typing-caret"/></p><div v-if="!demoShown||(section as any).complete" class="source-tags"><span v-for="source in section.sources" :key="source"><UiIcon name="file"/>{{source}}<UiIcon name="external"/></span></div></section><div v-if="!demoShown||demoPhase==='done'" class="answer-takeaway"><UiIcon name="lightbulb"/><p><strong>下一步建议</strong>把你关注的产品或行业告诉我，我可以继续按同样的结构细化。</p></div></template><template v-else-if="failed"><p class="answer-intro">本次搜索没有取得有效结果，我暂时无法提供经过核实的最新新闻。</p><section class="failure-answer"><h2>你可以这样继续</h2><p>稍后重新搜索，或把你想了解的主题、文章链接发给我，我可以帮你提炼重点。</p><div class="failure-options"><button @click="notice='预览中的重试按钮；不会调用真实搜索服务'"><UiIcon name="refresh"/>重新搜索</button><button @click="draft='帮我分析这篇文章：'"><UiIcon name="link"/>分析文章</button></div></section></template><div v-if="demoShown&&['preparing','tools','summarizing'].includes(demoPhase)" class="demo-waiting" role="status"><span class="waiting-dots"><i/><i/><i/></span><span>{{demoPhase==='preparing'?'正在准备任务，请稍等…':demoPhase==='tools'?'正在获取资料，工具返回后继续生成回答…':'资料已获取，正在整理回答…'}}</span></div><p v-if="demoShown&&demoPhase==='stopped'" class="demo-stopped">已停止，保留当前工具记录和已生成的内容。</p><footer v-if="!demoShown||demoPhase==='done'" class="preview-answer-actions"><button @click="copy"><UiIcon name="copy"/>复制</button><button aria-label="重新生成示例" @click="notice='这是样式示例，暂不调用模型'"><UiIcon name="refresh"/></button><button :class="{selected:liked}" aria-label="赞回答" @click="liked=!liked"><UiIcon name="thumb-up"/></button></footer></div></article></div></div><div class="composer-wrap"><form class="chat-composer welcome-composer" @submit.prevent="send"><div v-if="showAttachments&&previewAttachment" class="composer-attachments"><ChatAttachmentCard :file="previewAttachment" removable @remove="previewAttachment=undefined"/></div><textarea v-model="draft" rows="3" placeholder="输入你的问题，Enter 发送，Shift + Enter 换行…" aria-label="示例消息输入" @keydown.enter.exact.prevent="send"/><div class="composer-footer"><div class="composer-tools"><button type="button" class="upload-label" aria-label="添加附件" @click="notice='这是样式预览，暂不上传附件'"><UiIcon name="paperclip"/></button></div><div class="composer-send"><el-select v-model="agent" filterable placeholder="选择智能体" class="welcome-agent-select" aria-label="选择智能体"><template #prefix><UiIcon name="bot"/></template><el-option v-for="name in ['博查搜索助手','深度研究助手','写作助手']" :key="name" :value="name" :label="name"/></el-select><button class="chat-primary" type="submit" :disabled="!draft.trim()"><UiIcon name="send"/>发送</button></div></div></form></div><div v-if="notice" role="status" class="preview-toast" @click="notice=''">{{notice}}<UiIcon name="close"/></div></main></div></div></template>
<style scoped src="./chat-design-preview.css"></style>

<style scoped src="./defaultPage/conversation-welcome.css"></style>

<style scoped>.preview-user-content{display:flex;flex-direction:column;align-items:flex-end;gap:10px;min-width:0;max-width:80%}.preview-user-content .preview-user-bubble{max-width:100%}</style>
